window.RP_SESSION={"id":"S-e7fd3ef1ca47","messages":[{"id":"RP-0253948","time":"2026-08-29T04:14:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"사삭.","characters":["P-c93f55c91873"]},{"id":"RP-0253949","time":"2026-08-29T04:14:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"사사삭.","characters":["P-c93f55c91873"]},{"id":"RP-0253950","time":"2026-08-29T04:17:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"삭삭.","characters":["P-c93f55c91873"]},{"id":"RP-0253951","time":"2026-08-29T04:17:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"슥슥.","characters":["P-c93f55c91873"]},{"id":"RP-0253952","time":"2026-08-29T04:18:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"오늘의 잡일은 뭘까~~요¿","characters":["P-c93f55c91873"]},{"id":"RP-0253953","time":"2026-08-29T04:20:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"바로바로 짐말 빗질해주기!","characters":["P-c93f55c91873"]},{"id":"RP-0253954","time":"2026-08-29T04:23:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인이 석달 전쯤 사온 이 중부 샤이어는 하얀 털에 검은 물감을 뿌린 것 같은 점박이였는데, 덩치가 샤이어치고도 꽤나 컸습니다.\n\n거칠게 투레질하는 녀석에게 델타인은 손을 뻗었습니다.\n\n\"쉬이- 착하지.\"","characters":["P-c93f55c91873"]},{"id":"RP-0253955","time":"2026-08-29T04:26:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"기웃기웃.","characters":["P-89d5e8c6329e"]},{"id":"RP-0253956","time":"2026-08-29T04:27:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그렇습니다. 보고 싶었던 연인이 돌아왔다는 소식에 한걸음에 달려온 홍당무!","characters":["P-89d5e8c6329e"]},{"id":"RP-0253957","time":"2026-08-29T04:28:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"기웃기웃... 아직 한 번도 가보지 않은 마구간 근처를 서성이며 델타인을 몰래 힐끔힐끔...","characters":["P-89d5e8c6329e"]},{"id":"RP-0253958","time":"2026-08-29T04:28:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"보고 싶어서 왔다고 말하기엔 조금 부끄러운 탓에, 그저 기웃거리기만 합니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0253959","time":"2026-08-29T04:32:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"점박이 샤이어는 고삐를 당기며 마구 머리를 흔들어댔지만, 델타인은 끈질기게 녀석의 머리를 쓰다듬었습니다. 녀석이 몸을 돌리려 할 때마다 엉덩이를 밀치며 머리를 붙들었습니다.\n\n\"착하지, 착하지.\"","characters":["P-c93f55c91873"]},{"id":"RP-0253960","time":"2026-08-29T04:33:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"착… 착한…가? 아닌 거 같은데. 농장에서 키운 애들보다 더… 아, 하긴. 농장에서 키우면 거의 다 순하려나.","characters":["P-89d5e8c6329e"]},{"id":"RP-0253961","time":"2026-08-29T04:34:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…동물도 돌보는 거야, 델타인?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0253962","time":"2026-08-29T04:34:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"결국 용기를 내, 그의 앞에 서며 물어봅니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0253963","time":"2026-08-29T04:35:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"오, 누나? 언제부터 계셨어요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0253964","time":"2026-08-29T04:35:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"네가 착하지… 할 때부터?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0253965","time":"2026-08-29T04:35:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…딱히 착하진 않은 거 같지만.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0253966","time":"2026-08-29T04:36:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"험.\"","characters":["P-c93f55c91873"]},{"id":"RP-0253967","time":"2026-08-29T04:36:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-c93f55c91873"]},{"id":"RP-0253968","time":"2026-08-29T04:36:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 매력 판정 :\n[3] + [1] = [4]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0253969","time":"2026-08-29T04:36:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"커다란 몸뚱이가 꿈틀거리자 뒤로 밀려납니다.","characters":["P-c93f55c91873"]},{"id":"RP-0253970","time":"2026-08-29T04:36:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그르네요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0253971","time":"2026-08-29T04:37:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"내가 본 동물들은 농장에서 본 게 전부니까. 이러는 애들이 보통의 애들일 거야.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0253972","time":"2026-08-29T04:37:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"제가 이 녀석이 싸지르는 똥도 다 치우는데!\"","characters":["P-c93f55c91873"]},{"id":"RP-0253973","time":"2026-08-29T04:38:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"무심코 말의 엉덩이를 찰싹 때렸다가 말의 뒷다리가 후욱, 퍽!","characters":["P-c93f55c91873"]},{"id":"RP-0253974","time":"2026-08-29T04:38:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-c93f55c91873"]},{"id":"RP-0253975","time":"2026-08-29T04:38:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 체력 판정 :\n[8] + [0] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0253976","time":"2026-08-29T04:38:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"커헉…!\"","characters":["P-c93f55c91873"]},{"id":"RP-0253977","time":"2026-08-29T04:38:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…너, 너! 아니, 괜찮아?!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0253978","time":"2026-08-29T04:38:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"어째서인지 멀쩡하네요.","characters":["P-c93f55c91873"]},{"id":"RP-0253979","time":"2026-08-29T04:39:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"커흑, 거흑, 그윽….\"","characters":["P-c93f55c91873"]},{"id":"RP-0253980","time":"2026-08-29T04:39:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"큼큼, 흠. 험?\"","characters":["P-c93f55c91873"]},{"id":"RP-0253981","time":"2026-08-29T04:39:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"멀쩡한데요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0253982","time":"2026-08-29T04:39:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"얘를 진짜 어쩌지…","characters":["P-89d5e8c6329e"]},{"id":"RP-0253983","time":"2026-08-29T04:40:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…말들은 겁이 많잖아. 또 그렇게 하면 안 돼. 알겠지?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0253984","time":"2026-08-29T04:40:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"으이구, 여기 착한 애는 내가 칭찬해 줘야겠네.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0253985","time":"2026-08-29T04:41:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“앗, 누나. 저 이번 의뢰 나가서 착한 일 많이 했어요.”","characters":["P-c93f55c91873"]},{"id":"RP-0253986","time":"2026-08-29T04:42:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"그래? 무슨 일 했는데?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0253987","time":"2026-08-29T04:43:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“무슨 정령이 커져서 삐비빅 하고 빠바박 하길래 제가 존 씨랑 니콜라스랑 레마 씨를 솨솩! 그랬죠.”","characters":["P-c93f55c91873"]},{"id":"RP-0253988","time":"2026-08-29T04:43:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"최대한 친절한 설명인 듯합니다.","characters":["P-c93f55c91873"]},{"id":"RP-0253989","time":"2026-08-29T04:44:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"무슨 정령이 공격하려 했는데, 동료들이랑 같이 피했다는 얘기일까나…","characters":["P-89d5e8c6329e"]},{"id":"RP-0253990","time":"2026-08-29T04:44:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…오, 멋진 일 했네!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0253991","time":"2026-08-29T04:44:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"차, 착하지….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0253992","time":"2026-08-29T04:45:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"어색하게 델타인 머리를 쓰담쓰담.","characters":["P-89d5e8c6329e"]},{"id":"RP-0253993","time":"2026-08-29T04:45:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"…어째 너무 짐승 취급하는 건가 싶어져, 조금 미안해진 홍당무입니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0253994","time":"2026-08-29T04:48:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“음후후…우후후… 제가 마지막 일격을 날리고 모두를 구한 거죠.”","characters":["P-c93f55c91873"]},{"id":"RP-0253995","time":"2026-08-29T04:48:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인은 엘레나가 머리를 더 쉽게 쓰다듬도록 허리를 수구렸습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0253996","time":"2026-08-29T04:49:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"델타인이 웃는 소리에 웃음 꾹... 조금 귀엽다고 생각합니다...","characters":["P-89d5e8c6329e"]},{"id":"RP-0253997","time":"2026-08-29T04:50:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…그래? 그거 완전 멋지다! 엄청 착한 일 했네. 엄청 멋져! 최고야.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0253998","time":"2026-08-29T04:50:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"허리를 수그려주자, 두 손으로 머리 복복복...","characters":["P-89d5e8c6329e"]},{"id":"RP-0253999","time":"2026-08-29T04:50:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…역시 어둠대왕이네!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254000","time":"2026-08-29T04:51:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“아, 그정돈 아녜요.”","characters":["P-c93f55c91873"]},{"id":"RP-0254001","time":"2026-08-29T04:52:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-c93f55c91873"]},{"id":"RP-0254002","time":"2026-08-29T04:52:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"과한 칭찬은 별로 안 좋아하나 보네…","characters":["P-89d5e8c6329e"]},{"id":"RP-0254003","time":"2026-08-29T04:52:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"고개 끄덕끄덕...","characters":["P-89d5e8c6329e"]},{"id":"RP-0254004","time":"2026-08-29T04:53:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"막 엄청 큰 정령은 아녔는가 봐?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254005","time":"2026-08-29T04:53:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"막 이-따만한 크기가 아녔어?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254006","time":"2026-08-29T04:54:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"팔 휘적휘적...","characters":["P-89d5e8c6329e"]},{"id":"RP-0254007","time":"2026-08-29T04:56:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“어, 아뇨. 엄청 컸어요.”","characters":["P-c93f55c91873"]},{"id":"RP-0254008","time":"2026-08-29T04:56:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“근데, 음, 그 전까지 제가 하던 게 거의 없었걸랑요.”","characters":["P-c93f55c91873"]},{"id":"RP-0254009","time":"2026-08-29T04:58:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"그럴 수도 있지. 나도 그런 적 많아.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254010","time":"2026-08-29T04:59:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…뭘 해야 할지 모르겠고, 뭐라도 하기엔… 그게 다 내 신념을 벗어나는 일이고.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254011","time":"2026-08-29T05:00:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"그래도, 뭐라도 했잖아? 델타인은, 나랑 다르니까.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254012","time":"2026-08-29T05:00:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"망설이지 않는 모습이 좋아.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254013","time":"2026-08-29T05:00:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“오잉, 정말요?”","characters":["P-c93f55c91873"]},{"id":"RP-0254014","time":"2026-08-29T05:01:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“다들 저한테 생각 좀 하고 행동하라 하던데요?”","characters":["P-c93f55c91873"]},{"id":"RP-0254015","time":"2026-08-29T05:01:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254016","time":"2026-08-29T05:02:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"딱히 틀린 말은 아닌 듯해서, 다른 할 말을 찾습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0254017","time":"2026-08-29T05:02:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"……싸울 때만큼은, 생각을 너무 많이 하면 좀 그렇잖아?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254018","time":"2026-08-29T05:03:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"그러니까, 그럴 때 엄청 멋있는 거지.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254019","time":"2026-08-29T05:05:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"일리가 있네요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254020","time":"2026-08-29T05:05:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"누나는 역시 똑똑하셔요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254021","time":"2026-08-29T05:05:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"참, 말 빗질 좀 도와주실래요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0254022","time":"2026-08-29T05:08:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"응, 좋지!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254023","time":"2026-08-29T05:09:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"조심조심, 빗을 들고서... 말의 시야가 닿는 곳에 서서 빗질을 시작합니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0254024","time":"2026-08-29T05:09:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"삭삭... 슥슥...","characters":["P-89d5e8c6329e"]},{"id":"RP-0254027","time":"2026-08-29T05:10:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"!매력+1","characters":["P-89d5e8c6329e"]},{"id":"RP-0254028","time":"2026-08-29T05:10:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'Reggiano Elena'의 매력 판정 :\n[11] + [0] + [1] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0254034","time":"2026-08-29T05:12:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…생각보다 순한 거 같은데? 아까는 놀라서 그랬나 봐.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254035","time":"2026-08-29T05:13:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"옳지, 착하지…. 시원하다, 그치?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254036","time":"2026-08-29T05:14:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"우, 우와….\"","characters":["P-c93f55c91873"]},{"id":"RP-0254037","time":"2026-08-29T05:15:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"너도 옆에서부터 시작하면 아까처럼 발로 차지는 않을 거야.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254038","time":"2026-08-29T05:15:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…때리지도 말고!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254039","time":"2026-08-29T05:16:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"네 생각에도, 내가 갑자기 네 엉덩이 때리면 좋겠어?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254040","time":"2026-08-29T10:20:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엘레나 누나가 때렸음 이유가 있겠죠 뭐.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254041","time":"2026-08-29T10:26:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"점박이 샤이어가 작게 푸릉거리자, 델타인은 안장에서 사료를 꺼내 녀석에게 먹였습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0254042","time":"2026-08-29T10:26:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"분변도 치워주고, 깔짚도 자주 갈아주고, 밥도 간혹 먹이는데 누나 말을 더 듣다니!","characters":["P-c93f55c91873"]},{"id":"RP-0254043","time":"2026-08-29T10:34:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"하긴, 엇나가면 때려주기로 했던 건 나였지…","characters":["P-89d5e8c6329e"]},{"id":"RP-0254044","time":"2026-08-29T10:34:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…때리지만 않으면, 널 더 좋아할 거야.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254045","time":"2026-08-29T10:35:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"아니면 곧 나도 발로 걷어찰 수도 있지! …안 그러면 좋겠지만. 그거 엄청 아프단 말이야.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254046","time":"2026-08-29T11:05:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"험, 그건 좀 아프겠네요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254047","time":"2026-08-29T11:05:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인은 말빗을 받아들고 갈기를 위주로 천천히 쓸어보았습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0254048","time":"2026-08-29T11:06:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엘레나 누나는 뭐하고 지내셨어요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0254049","time":"2026-08-29T11:47:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…어? 음….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254050","time":"2026-08-29T11:48:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"딱히 한 건 없는데. 그냥 방에서만 있다고 하면 좀 민망하잖아! 너무 게을러 보이고…","characters":["P-89d5e8c6329e"]},{"id":"RP-0254051","time":"2026-08-29T11:49:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…너, 기다렸어. 그냥, 네 생각을 하면서. 언제 오려나, 하고….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254052","time":"2026-08-29T11:49:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“도서관 사서 니콜라스 아세요? 걔가 제 친구인데 이번에 가…이… 네?“","characters":["P-c93f55c91873"]},{"id":"RP-0254053","time":"2026-08-29T11:49:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"”저를 기다리셨다구요?“","characters":["P-c93f55c91873"]},{"id":"RP-0254054","time":"2026-08-29T11:50:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“아이고, 제가 처리 안하고 떠난 일이 있었나보네요.“","characters":["P-c93f55c91873"]},{"id":"RP-0254055","time":"2026-08-29T11:52:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"도서관 사서? 엄청 똑똑하신 분이겠네….","characters":["P-89d5e8c6329e"]},{"id":"RP-0254056","time":"2026-08-29T11:52:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…그런 건 아니고, 델타인이 없으면 조금 불안해. 네 생각을 하는 게 마음이 제일 편하고.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254057","time":"2026-08-29T11:53:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"……그리고, 연인 기다리는 건 당연한 거 아냐? 잊은 거 아니지, 우리 연인인 거?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254058","time":"2026-08-29T11:54:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“오…….”","characters":["P-c93f55c91873"]},{"id":"RP-0254059","time":"2026-08-29T11:55:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“잊은 건 아닌데, 기다리기까지 하실 줄 몰랐어요.”","characters":["P-c93f55c91873"]},{"id":"RP-0254060","time":"2026-08-29T11:55:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“어쩐지, 저도 막 꿈에 엘레나 누나가 나오고 하더라니!”","characters":["P-c93f55c91873"]},{"id":"RP-0254061","time":"2026-08-29T11:56:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"보, 보통 다들 기다리기까지 하진 않나? 하긴, 모험가고 그러니까 각자 인생 살고 그러는 건가…?","characters":["P-89d5e8c6329e"]},{"id":"RP-0254062","time":"2026-08-29T11:56:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…아, 어, 음.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254063","time":"2026-08-29T11:57:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"미안해, 다음부터는 안 기다릴게. 기다려도 되는 줄 알았어….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254064","time":"2026-08-29T11:57:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"꾸, 꿈에서 나랑 뭐했는데? 내가 나오다니. 신기하네… 하, 하하….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254065","time":"2026-08-29T12:36:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“오, 아녜요. 기다리셔도 돼요. 기다리고 싶음 기다려야죠. 저도 사실 꿈에서 엘레나 누나를 기다렸는지도 몰라요.”","characters":["P-c93f55c91873"]},{"id":"RP-0254066","time":"2026-08-29T12:36:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-c93f55c91873"]},{"id":"RP-0254067","time":"2026-08-29T12:36:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 지능 판정 :\n[8] + [4] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0254068","time":"2026-08-29T12:37:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“제 꿈에서 누나가 나오셔서… 저를 막 때려눕히고 옷을 찢으시더라고요.”","characters":["P-c93f55c91873"]},{"id":"RP-0254069","time":"2026-08-29T12:38:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“그러더니 저를 꽁꽁 묶으시는 거 있죠?”","characters":["P-c93f55c91873"]},{"id":"RP-0254070","time":"2026-08-29T12:39:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"……그거, 기다렸다고 표현해도 되는 거 맞아?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254071","time":"2026-08-29T12:40:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"내, 내가 너를 때려눕혔어…? 옷을, 찢고… 묶고?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254072","time":"2026-08-29T12:40:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"충격받은 얼굴. 도대체 날 어떻게 생각하길래… 지, 짐승 같다고 생각하나? 야만적인?","characters":["P-89d5e8c6329e"]},{"id":"RP-0254073","time":"2026-08-29T12:41:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…그러고 꿈에서 깬 거야? 그 이후에는…? 내가 뭐, 시장에 너를 팔기라도 했어?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254074","time":"2026-08-29T12:52:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"“우… 아뇨. 그냥 가둬놓으셨어요.“","characters":["P-c93f55c91873"]},{"id":"RP-0254075","time":"2026-08-29T12:55:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"나, 날 도대체 어떻게 보고 있는 거… 아, 아닌가. 델타인이 그런 취향인 건가…? 그런 걸 좋아한다는 사람을 들은 적 있는 거 같기도….","characters":["P-89d5e8c6329e"]},{"id":"RP-0254076","time":"2026-08-29T12:56:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"……그런 게 좋아? 막, 내가 너 옷 찢고 그러는 거…?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254077","time":"2026-08-29T12:56:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"심각한 표정. 진지한 표정.","characters":["P-89d5e8c6329e"]},{"id":"RP-0254078","time":"2026-08-29T12:56:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"오, 아뇨.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254079","time":"2026-08-29T12:57:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"누나가 하신다면 어쩔 수 없지만 좋지는 않죠.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254080","time":"2026-08-29T12:57:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인은 어깨를 으쓱해보입니다.\n\n\"뭐, 다른 마법 쓰는 분들도 무슨 꿈을 꾸셨던 것 같아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254081","time":"2026-08-29T12:57:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그게 사실 실제로 저희가 맞닥뜨린 일인데… 흠, 예지몽 아닐까요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0254082","time":"2026-08-29T13:00:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…네가 싫다며. 그럼 예지몽 아냐. 난 그런 일 안 할래.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254083","time":"2026-08-29T13:01:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"좋아요!\"","characters":["P-c93f55c91873"]},{"id":"RP-0254084","time":"2026-08-29T13:01:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"……옷 찢는 건, 잘 모르겠어. 힘 조절 잘 못하면…… 가끔 그래서.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254085","time":"2026-08-29T13:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"점박이의 갈기를 빗던 델타인이 입을 떡 벌립니다.\n\n\"어우, 전 옷이 네 벌 밖에 없어요. 제발 절 찢지 마세요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254086","time":"2026-08-29T13:05:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"혀를 내두르며 짐말용 안장을 올렸습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0254087","time":"2026-08-29T13:07:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"진짜? 그럼, 다음에 같이 옷 사러 가자. 내가 사줄게!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254088","time":"2026-08-29T13:07:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"어차피, 당분간 위험한 의뢰는 안 나갈 거 같기도 해서… 나도 예쁜 옷 좀 살까 싶거든.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254089","time":"2026-08-29T13:09:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"오? 좋아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254090","time":"2026-08-29T13:09:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그럼 누나 옷은 제가 봐드리는 거예요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0254091","time":"2026-08-29T13:09:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인은 마구간 청소 도구들과 빗을 한 군데에 정리해두곤 나왔습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0254092","time":"2026-08-29T13:10:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"와자뵤, 완전 기대되네요!\"","characters":["P-c93f55c91873"]},{"id":"RP-0254093","time":"2026-08-29T13:11:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"응? 그래! 네가 좋아하는 옷이면 뭐든 입지, 뭐!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254094","time":"2026-08-29T13:19:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"우후후… 으흐흐….\"","characters":["P-c93f55c91873"]},{"id":"RP-0254095","time":"2026-08-29T13:19:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"좋아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254096","time":"2026-08-29T13:19:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"우물가에서 손을 깨끗히 씻은 뒤, 길드 건물로 돌아가면서도 입을 멈추지 않았습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0254097","time":"2026-08-29T13:19:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"제가 곰이랑 싸운 이야기는 아직 안했죠?\"","characters":["P-c93f55c91873"]},{"id":"RP-0254098","time":"2026-08-29T13:25:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"응, 아직 안 했어. …안 다쳤어?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254099","time":"2026-08-29T13:25:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"안 다쳤죠!\"","characters":["P-c93f55c91873"]},{"id":"RP-0254100","time":"2026-08-29T13:25:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"심지어 맨손으로 싸웠다구요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0254101","time":"2026-08-29T13:25:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"얼마나 영웅적인 대결이었는지!\"","characters":["P-c93f55c91873"]},{"id":"RP-0254102","time":"2026-08-29T13:30:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인은 태어난지 1, 2년쯤 된 새끼 곰이란 사실을 쏙 빼놓고 자랑했습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0254103","time":"2026-08-29T13:31:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"육포를 미끼로 쓰고 책으로 두들겨 팼다고 떠들었답니다.","characters":["P-c93f55c91873"]},{"id":"RP-0254105","time":"2026-08-29T13:41:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"책으로 팬 거면… 맨손으로 싸운 건 아니지 않나? 하긴, 진짜 맨손이었으면 팔 한쪽은 이미 먹혔을테니까.","characters":["P-89d5e8c6329e"]},{"id":"RP-0254106","time":"2026-08-29T13:42:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"곰이랑 싸우다니, 멋지네. 그것도 안 다치고 싸우고…\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254107","time":"2026-08-29T13:43:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"육포를 미끼로 썼다니 대단하다! 안 다치고 싸운 게 제일 대단해.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254108","time":"2026-08-29T13:44:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"역시 델타인이구나…. 전에도 그렇고, 겁먹지 않는 거 같아서 참 멋있는 거 같아. 난 겁쟁이인데.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0254109","time":"2026-08-29T13:51:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"음후후… 너무 띄워주지 마세요. 저도 곰도 최선을 다한 사나이들의 결투였으니까요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254110","time":"2026-08-29T13:51:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"새끼 곰은 암컷이었지만!","characters":["P-c93f55c91873"]},{"id":"RP-0254111","time":"2026-08-29T13:52:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"결투의 좋은 점이란 게 그거죠. 이기든 지든 무언가를 얻거든요. 전 영광을 얻었고, 곰 녀석은 자유를 얻었죠.\"","characters":["P-c93f55c91873"]},{"id":"RP-0254112","time":"2026-08-29T13:52:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인은 진심으로 자기가 이겼다 믿고 있습니다. 그러니 이리도 스스럼없이 떠벌리는 거겠지요.","characters":["P-c93f55c91873"]},{"id":"RP-0254113","time":"2026-08-29T13:53:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이렇게 하루가 또 지나갑니다….","characters":["P-c93f55c91873"]},{"id":"RP-0254114","time":"2026-08-29T13:53:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c93f55c91873"]},{"id":"RP-0254115","time":"2026-08-29T13:53:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
